    BIZ_TYPE          VARCHAR(32)       NULL COMMENT '业务类型',
    BIZ_ID            VARCHAR(64)       NULL COMMENT '业务ID',
    BIZ_TAG           VARCHAR(64)       NULL COMMENT '业务标签',
    REMARK            VARCHAR(500)      NULL COMMENT '备注',
