    CREATOR_ID     VARCHAR(32)      NULL COMMENT '创建人ID',
    MODIFY_TIME    VARCHAR(20)      NULL COMMENT '修改时间',
    MODIFIER_ID    VARCHAR(32)      NULL COMMENT '修改人ID',
    PRIMARY KEY (ID),
    UNIQUE KEY UK_MESSAGE_CONTEXT_KEY_LOCALE (TENANT_ID, ORG_ID, MESSAGE_KEY, LOCALE),
    INDEX IDX_MESSAGE_CONTEXT (TENANT_ID, ORG_ID)
) COMMENT='多语言消息表';

-- PEACH_NOTICE.sql
CREATE TABLE PEACH_NOTICE
(
    ID                  VARCHAR(64)  NOT NULL COMMENT '通知ID',
    NOTICE_CODE         VARCHAR(64)  NOT NULL COMMENT '通知编码',
    TITLE_MESSAGE_KEY   VARCHAR(128)     NULL COMMENT '标题消息Key',
    CONTENT_MESSAGE_KEY VARCHAR(128)     NULL COMMENT '内容消息Key',
    NOTICE_TYPE         VARCHAR(32)      NULL COMMENT '通知类型',
    PRIORITY            INT              NULL COMMENT '优先级',
    PUBLISH_STATUS      VARCHAR(32)      NULL COMMENT '发布状态',
    EFFECTIVE_FROM      VARCHAR(20)      NULL COMMENT '生效开始时间',
    EFFECTIVE_TO        VARCHAR(20)      NULL COMMENT '生效结束时间',
    READ_COUNT          INT              NULL COMMENT '阅读次数',
    INBOX_ENABLED       INT              NULL COMMENT '是否启用收件箱',
    STATUS              INT              NULL COMMENT '状态',
    TENANT_ID           VARCHAR(32)  NOT NULL COMMENT '租户ID',
    ORG_ID              VARCHAR(32)  NOT NULL COMMENT '机构ID',
    CREATED_TIME        VARCHAR(20)      NULL COMMENT '创建时间',
    CREATOR_ID          VARCHAR(32)      NULL COMMENT '创建人ID',
    MODIFY_TIME         VARCHAR(20)      NULL COMMENT '修改时间',
    MODIFIER_ID         VARCHAR(32)      NULL COMMENT '修改人ID',
    PRIMARY KEY (ID),
    UNIQUE KEY UK_NOTICE_CONTEXT_CODE (TENANT_ID, ORG_ID, NOTICE_CODE),
    INDEX IDX_NOTICE_CONTEXT_STATUS (TENANT_ID, ORG_ID, PUBLISH_STATUS, STATUS)
) COMMENT='通知公告表';

-- PEACH_NOTICE_READ_RECORD.sql
CREATE TABLE PEACH_NOTICE_READ_RECORD
(
    ID            VARCHAR(64) NOT NULL COMMENT '主键ID',
    NOTICE_CODE   VARCHAR(64) NOT NULL COMMENT '通知编码',
    READ_USER_ID  VARCHAR(64) NOT NULL COMMENT '阅读用户ID',
    READ_TIME     VARCHAR(20)     NULL COMMENT '阅读时间',
    TENANT_ID    VARCHAR(32) NOT NULL COMMENT '租户ID',
    ORG_ID       VARCHAR(32) NOT NULL COMMENT '机构ID',
    CREATED_TIME  VARCHAR(20)     NULL COMMENT '创建时间',
    CREATOR_ID    VARCHAR(32)     NULL COMMENT '创建人ID',
    MODIFY_TIME   VARCHAR(20)     NULL COMMENT '修改时间',
    MODIFIER_ID   VARCHAR(32)     NULL COMMENT '修改人ID',
    PRIMARY KEY (ID),
    UNIQUE KEY UK_NOTICE_READ_CONTEXT (TENANT_ID, ORG_ID, NOTICE_CODE, READ_USER_ID),
    INDEX IDX_NOTICE_READ_CONTEXT_USER (TENANT_ID, ORG_ID, READ_USER_ID)
) COMMENT='通知阅读记录表';

-- PEACH_ORGANIZATION.sql
CREATE TABLE PEACH_ORGANIZATION (
    ORG_ID        VARCHAR(32)  NOT NULL COMMENT '机构ID',
    TENANT_ID     VARCHAR(32)  NOT NULL COMMENT '租户ID',
    ORG_CODE      VARCHAR(64)  NOT NULL COMMENT '机构编码',
    ORG_NAME      VARCHAR(128) NOT NULL COMMENT '机构名称',
    STATUS        VARCHAR(16)  DEFAULT 'ENABLE' COMMENT '状态',
    SORT_NUM      INT          DEFAULT 0 COMMENT '排序',
    IS_DELETE     INT          DEFAULT 0 COMMENT '逻辑删除',
    CREATED_TIME  VARCHAR(20)  NULL COMMENT '创建时间',
    CREATOR_ID    VARCHAR(32)  NULL COMMENT '创建人ID',
    MODIFY_TIME   VARCHAR(20)  NULL COMMENT '修改时间',
    MODIFIER_ID   VARCHAR(32)  NULL COMMENT '修改人ID',
    PRIMARY KEY (ORG_ID),
    UNIQUE KEY UK_ORG_CODE (TENANT_ID, ORG_CODE),
    INDEX IDX_ORG_TENANT_ID (TENANT_ID)
);

-- PEACH_RESOURCE.sql
CREATE TABLE PEACH_RESOURCE
(
    RESOURCE_ID      VARCHAR(32)  NOT  NULL COMMENT '资源ID',
    FUNC_CODE        VARCHAR(128)      NULL COMMENT '功能编码',
    RESOURCE_TYPE    VARCHAR(20)       NULL COMMENT '资源类型',
    RESOURCE_CODE    VARCHAR(64)       NULL COMMENT '资源编码',
    RESOURCE_NAME    VARCHAR(32)       NULL COMMENT '资源名称',
    TENANT_ID        VARCHAR(32)  NOT NULL COMMENT '租户ID',
    APP_ID           VARCHAR(32)  NOT NULL COMMENT '应用ID',
    CREATED_TIME     VARCHAR(20)       NULL COMMENT '创建时间',
    CREATOR_ID       VARCHAR(32)       NULL COMMENT '创建人ID',
    MODIFY_TIME      VARCHAR(20)       NULL COMMENT '修改时间',
    MODIFIER_ID      VARCHAR(32)       NULL COMMENT '修改人ID',
    IS_DELETE        TINYINT(1)   DEFAULT 0 COMMENT '是否删除',
    PRIMARY KEY (RESOURCE_ID),
    UNIQUE KEY UK_RESOURCE_TENANT_APP_FUNC_CODE (TENANT_ID, APP_ID, FUNC_CODE, RESOURCE_CODE)
) COMMENT='资源表';

CREATE INDEX RESOURCE_BUSI_IDX
    ON PEACH_RESOURCE (TENANT_ID, APP_ID, FUNC_CODE, RESOURCE_CODE);

-- PEACH_ROLE.sql
CREATE TABLE PEACH_ROLE
(
    ROLE_ID          VARCHAR(32)  NOT NULL COMMENT '角色ID',
    TENANT_ID        VARCHAR(32)  NOT NULL COMMENT '租户ID',
    ORG_ID           VARCHAR(32)  NOT NULL COMMENT '机构ID',
    ROLE_CODE        VARCHAR(20)  NOT NULL COMMENT '角色编码',
    FISCAL           SMALLINT(4)  NOT NULL COMMENT '年度',
    ROLE_NAME        VARCHAR(64)  NULL COMMENT '角色名称',
    ROLE_DESC        VARCHAR(64)  NULL COMMENT '角色描述',
    ROLE_SCOPE       VARCHAR(20)  NULL COMMENT '角色范围',
    ROLE_TYPE        VARCHAR(20)  NULL COMMENT '角色类型',
    CREATED_TIME     VARCHAR(20)  NULL COMMENT '创建时间',
    CREATOR_ID       VARCHAR(32)  NULL COMMENT '创建人ID',
    MODIFY_TIME      VARCHAR(20)  NULL COMMENT '修改时间',
    MODIFIER_ID      VARCHAR(32)  NULL COMMENT '修改人ID',
    IS_DELETE        TINYINT(1)   DEFAULT 0 NULL COMMENT '是否删除',
    SKIP_URL         VARCHAR(64)  NULL COMMENT '角色登陆跳转',
    PRIMARY KEY (ROLE_ID)
) COMMENT='角色表';

CREATE UNIQUE INDEX UK_ROLE_CODE
    ON PEACH_ROLE (TENANT_ID, ORG_ID, ROLE_CODE, FISCAL);

CREATE INDEX IDX_ROLE_TENANT_ORG
    ON PEACH_ROLE (TENANT_ID, ORG_ID);

-- PEACH_ROUTER.sql
CREATE TABLE PEACH_ROUTER
(
    ROUTER_ID     VARCHAR(64)  NOT NULL COMMENT '主键',
    ROUTER_CODE   VARCHAR(100) NOT NULL COMMENT '路由代码',
    ROUTER_NAME   VARCHAR(100) NOT NULL COMMENT '路由名称',
    ROUTER_URL    VARCHAR(100) NOT NULL COMMENT '路由路径',
    FILE_PATH     VARCHAR(255) NOT NULL COMMENT '文件路径',
    IS_AUTH       TINYINT(1) DEFAULT 1 NOT NULL COMMENT '是否需要授权',
    IS_CACHE      TINYINT(1) DEFAULT 1 NOT NULL COMMENT '是否缓存',
    MODULE_CODE   VARCHAR(10)  NOT NULL COMMENT '模块代码',
    ROUTER_LEVEL  INT(4) NOT NULL COMMENT '路由级次',
    TENANT_ID     VARCHAR(32)  NOT NULL COMMENT '租户ID',
    APP_ID        VARCHAR(32)  NOT NULL COMMENT '应用ID',
    CREATED_TIME  VARCHAR(20)  NULL COMMENT '创建时间',
    CREATOR_ID    VARCHAR(32)  NULL COMMENT '创建人ID',
    MODIFY_TIME   VARCHAR(20)  NULL COMMENT '修改时间',
    MODIFIER_ID   VARCHAR(32)  NULL COMMENT '修改人ID',
    PRIMARY KEY (ROUTER_ID),
    UNIQUE KEY UK_ROUTER_TENANT_APP_CODE (TENANT_ID, APP_ID, ROUTER_CODE),
    UNIQUE KEY UK_ROUTER_TENANT_APP_URL (TENANT_ID, APP_ID, ROUTER_URL),
    INDEX IDX_ROUTER_TENANT_APP (TENANT_ID, APP_ID)
) COMMENT='路由管理表';

-- PEACH_SCHEDULER_EXECUTION.sql
CREATE TABLE PEACH_SCHEDULER_EXECUTION
(
    EXECUTION_ID      VARCHAR(64)  NOT NULL COMMENT '执行实例 ID',
    JOB_ID            BIGINT       NOT NULL COMMENT '任务主键',
    JOB_CODE          VARCHAR(128) NOT NULL COMMENT '稳定任务编码',
    OCCURRENCE_KEY    VARCHAR(192) NOT NULL COMMENT '逻辑 occurrence 幂等键',
    TRIGGER_TYPE      VARCHAR(32)  NOT NULL COMMENT '触发类型：SCHEDULED、MANUAL',
    SCHEDULED_TIME    DATETIME(3)  NOT NULL COMMENT '计划执行时间',
    STATE             VARCHAR(32)  NOT NULL COMMENT '执行生命周期状态',
    ATTEMPT           INT          NOT NULL DEFAULT 1 COMMENT '当前尝试次数',
    EXECUTOR_INSTANCE VARCHAR(128) NULL COMMENT '当前执行器实例标识',
    LEASE_UNTIL       DATETIME(3)  NULL COMMENT '执行租约过期时间',
    NEXT_RETRY_TIME   DATETIME(3)  NULL COMMENT '下次允许重试时间',
    START_TIME        DATETIME(3)  NULL COMMENT '实际开始时间',
    FINISH_TIME       DATETIME(3)  NULL COMMENT '实际结束时间',
    DURATION_MS       BIGINT       NULL COMMENT '执行耗时毫秒数',
    TRACE_ID          VARCHAR(128) NULL COMMENT '链路追踪 ID',
    ERROR_TYPE        VARCHAR(128) NULL COMMENT '失败类型',
    ERROR_MESSAGE     VARCHAR(1000) NULL COMMENT '脱敏后的失败摘要',
    VERSION           BIGINT       NOT NULL DEFAULT 0 COMMENT '乐观锁版本号',
    CREATED_TIME      DATETIME(3)  NOT NULL COMMENT '创建时间',
    MODIFY_TIME       DATETIME(3)  NOT NULL COMMENT '修改时间',
    PRIMARY KEY (EXECUTION_ID),
    UNIQUE KEY UK_SCHEDULER_EXECUTION_OCCURRENCE (OCCURRENCE_KEY),
    KEY IDX_SCHEDULER_EXECUTION_JOB_TIME (JOB_ID, CREATED_TIME),
    KEY IDX_SCHEDULER_EXECUTION_STATE_TIME (STATE, CREATED_TIME),
    KEY IDX_SCHEDULER_EXECUTION_LEASE (STATE, LEASE_UNTIL),
    KEY IDX_SCHEDULER_EXECUTION_RETRY (STATE, NEXT_RETRY_TIME),
    KEY IDX_SCHEDULER_EXECUTION_JOB_CODE (JOB_CODE)
) COMMENT='调度逻辑执行 occurrence 表';

-- PEACH_SCHEDULER_EXECUTION_ATTEMPT.sql
CREATE TABLE PEACH_SCHEDULER_EXECUTION_ATTEMPT
(
    EXECUTION_ID      VARCHAR(64)  NOT NULL COMMENT '执行实例 ID',
    ATTEMPT_NO        INT          NOT NULL COMMENT '尝试序号',
    EXECUTOR_INSTANCE VARCHAR(128) NULL COMMENT '执行器实例标识',
    STATE             VARCHAR(32)  NOT NULL COMMENT '尝试状态',
    START_TIME        DATETIME(3)  NOT NULL COMMENT '尝试开始时间',
    FINISH_TIME       DATETIME(3)  NULL COMMENT '尝试结束时间',
    DURATION_MS       BIGINT       NULL COMMENT '尝试耗时毫秒数',
    ERROR_TYPE        VARCHAR(128) NULL COMMENT '失败类型',
    ERROR_MESSAGE     VARCHAR(1000) NULL COMMENT '脱敏后的失败摘要',
    CREATED_TIME      DATETIME(3)  NOT NULL COMMENT '创建时间',
    PRIMARY KEY (EXECUTION_ID, ATTEMPT_NO),
    KEY IDX_SCHEDULER_ATTEMPT_TIME (CREATED_TIME),
    KEY IDX_SCHEDULER_ATTEMPT_STATE (STATE, CREATED_TIME)
) COMMENT='调度执行尝试历史表';

-- PEACH_SCHEDULER_HANDLER.sql
CREATE TABLE PEACH_SCHEDULER_HANDLER
(
    ID                  BIGINT       NOT NULL AUTO_INCREMENT COMMENT 'Handler 主键',
    APPLICATION_NAME    VARCHAR(128) NOT NULL COMMENT '业务应用名称',
    HANDLER_NAME        VARCHAR(128) NOT NULL COMMENT 'Handler 名称',
    DESCRIPTION         VARCHAR(512) NULL COMMENT 'Handler 说明',
    STATUS              VARCHAR(32)  NOT NULL COMMENT '状态：ONLINE、OFFLINE',
    INSTANCE_ID         VARCHAR(128) NULL COMMENT '最近上报实例标识',
    LAST_HEARTBEAT_TIME DATETIME(3)  NOT NULL COMMENT '最近心跳时间',
    CREATED_TIME        DATETIME(3)  NOT NULL COMMENT '创建时间',
    MODIFY_TIME         DATETIME(3)  NOT NULL COMMENT '修改时间',
    PRIMARY KEY (ID),
    UNIQUE KEY UK_SCHEDULER_HANDLER (APPLICATION_NAME, HANDLER_NAME),
    KEY IDX_SCHEDULER_HANDLER_STATUS (STATUS, LAST_HEARTBEAT_TIME)
) COMMENT='调度 Handler 注册白名单表';

-- PEACH_SCHEDULER_JOB.sql
CREATE TABLE PEACH_SCHEDULER_JOB
(
    ID                     BIGINT       NOT NULL AUTO_INCREMENT COMMENT '任务主键',
    JOB_CODE               VARCHAR(128) NOT NULL COMMENT '稳定任务编码，全局唯一',
    JOB_NAME               VARCHAR(128) NOT NULL COMMENT '任务名称',
    APPLICATION_NAME       VARCHAR(128) NOT NULL COMMENT '目标业务应用名称',
    HANDLER_NAME           VARCHAR(128) NOT NULL COMMENT '目标 Handler 名称',
    DESCRIPTION            VARCHAR(512) NULL COMMENT '任务说明',
    SCHEDULE_TYPE          VARCHAR(32)  NOT NULL COMMENT '调度类型：CRON、FIXED_RATE、ONCE',
    CRON_EXPRESSION        VARCHAR(128) NULL COMMENT 'Quartz Cron 表达式',
    INTERVAL_SECONDS       BIGINT       NULL COMMENT '固定周期秒数',
    START_AT               DATETIME(3)  NULL COMMENT '调度起始时间',
    TIME_ZONE              VARCHAR(64)  NOT NULL DEFAULT 'Asia/Shanghai' COMMENT '调度时区',
    MISFIRE_POLICY         VARCHAR(32)  NOT NULL COMMENT '错过触发策略',
    CONCURRENCY_POLICY     VARCHAR(32)  NOT NULL COMMENT '并发策略：ALLOW、SKIP_IF_RUNNING、DISALLOW',
    TIMEOUT_MS             BIGINT       NOT NULL COMMENT '单次执行超时毫秒数',
    MAX_ATTEMPTS           INT          NOT NULL DEFAULT 1 COMMENT '最大执行次数，含首次',
    RETRY_INTERVAL_SECONDS INT          NOT NULL DEFAULT 60 COMMENT '重试间隔秒数',
    PARAMETERS_JSON        LONGTEXT     NULL COMMENT '任务参数 JSON，禁止写入凭据字段',
    STATE                  VARCHAR(32)  NOT NULL COMMENT '任务生命周期状态',
    SCHEDULE_VERSION       BIGINT       NOT NULL DEFAULT 1 COMMENT '调度定义版本号',
    SYNC_STATUS            VARCHAR(32)  NOT NULL COMMENT 'Provider 同步状态：PENDING、SYNCED、FAILED',
    LAST_SYNC_ERROR        VARCHAR(1000) NULL COMMENT '最近一次同步失败摘要',
    NEXT_FIRE_TIME         DATETIME(3)  NULL COMMENT '下次计划触发时间',
    LAST_FIRE_TIME         DATETIME(3)  NULL COMMENT '最近一次计划触发时间',
    VERSION                BIGINT       NOT NULL DEFAULT 0 COMMENT '乐观锁版本号',
    CREATOR_ID             VARCHAR(64)  NULL COMMENT '创建人 ID',
    CREATED_TIME           DATETIME(3)  NOT NULL COMMENT '创建时间',
    MODIFIER_ID            VARCHAR(64)  NULL COMMENT '修改人 ID',
    MODIFY_TIME            DATETIME(3)  NOT NULL COMMENT '修改时间',
    PRIMARY KEY (ID),
    UNIQUE KEY UK_SCHEDULER_JOB_CODE (JOB_CODE),
    KEY IDX_SCHEDULER_JOB_APP_HANDLER (APPLICATION_NAME, HANDLER_NAME),
    KEY IDX_SCHEDULER_JOB_STATE (STATE),
    KEY IDX_SCHEDULER_JOB_SYNC (SYNC_STATUS, MODIFY_TIME),
    KEY IDX_SCHEDULER_JOB_MODIFY_TIME (MODIFY_TIME)
) COMMENT='调度任务定义表';

-- PEACH_SCHEDULER_JOB_VERSION.sql
CREATE TABLE PEACH_SCHEDULER_JOB_VERSION
(
    ID                     BIGINT       NOT NULL AUTO_INCREMENT COMMENT '快照主键',
    JOB_ID                 BIGINT       NOT NULL COMMENT '任务主键',
    SCHEDULE_VERSION       BIGINT       NOT NULL COMMENT '调度定义版本号',
    JOB_CODE               VARCHAR(128) NOT NULL COMMENT '稳定任务编码',
    APPLICATION_NAME       VARCHAR(128) NOT NULL COMMENT '目标业务应用名称',
    HANDLER_NAME           VARCHAR(128) NOT NULL COMMENT '目标 Handler 名称',
    SCHEDULE_TYPE          VARCHAR(32)  NOT NULL COMMENT '调度类型',
    CRON_EXPRESSION        VARCHAR(128) NULL COMMENT 'Quartz Cron 表达式',
    INTERVAL_SECONDS       BIGINT       NULL COMMENT '固定周期秒数',
    START_AT               DATETIME(3)  NULL COMMENT '调度起始时间',
    TIME_ZONE              VARCHAR(64)  NOT NULL COMMENT '调度时区',
    MISFIRE_POLICY         VARCHAR(32)  NOT NULL COMMENT '错过触发策略',
    CONCURRENCY_POLICY     VARCHAR(32)  NOT NULL COMMENT '并发策略',
    TIMEOUT_MS             BIGINT       NOT NULL COMMENT '单次执行超时毫秒数',
    MAX_ATTEMPTS           INT          NOT NULL COMMENT '最大执行次数',
    RETRY_INTERVAL_SECONDS INT          NOT NULL COMMENT '重试间隔秒数',
    PARAMETERS_JSON        LONGTEXT     NULL COMMENT '任务参数 JSON',
    STATE                  VARCHAR(32)  NOT NULL COMMENT '快照时刻任务状态',
    CREATED_TIME           DATETIME(3)  NOT NULL COMMENT '快照创建时间',
    CREATOR_ID             VARCHAR(64)  NULL COMMENT '快照创建人 ID',
    PRIMARY KEY (ID),
    UNIQUE KEY UK_SCHEDULER_JOB_VERSION (JOB_ID, SCHEDULE_VERSION),
    KEY IDX_SCHEDULER_JOB_VERSION_CODE (JOB_CODE),
    KEY IDX_SCHEDULER_JOB_VERSION_TIME (CREATED_TIME)
) COMMENT='调度任务定义版本快照表';

-- PEACH_SCHEDULER_OPERATION_LOG.sql
CREATE TABLE PEACH_SCHEDULER_OPERATION_LOG
(
    ID           BIGINT       NOT NULL AUTO_INCREMENT COMMENT '操作日志主键',
    OPERATION    VARCHAR(64)  NOT NULL COMMENT '操作编码，如 RUN、RETRY、CANCEL',
    TARGET_TYPE  VARCHAR(32)  NOT NULL COMMENT '目标类型：JOB、EXECUTION',
    TARGET_ID    VARCHAR(128) NOT NULL COMMENT '目标标识',
    OPERATOR_ID  VARCHAR(64)  NULL COMMENT '操作人 ID',
    REASON       VARCHAR(512) NULL COMMENT '操作原因',
    RESULT       VARCHAR(32)  NOT NULL COMMENT '操作结果：SUCCESS、FAILED',
    CREATED_TIME DATETIME(3)  NOT NULL COMMENT '创建时间',
    PRIMARY KEY (ID),
    KEY IDX_SCHEDULER_OPERATION_TARGET (TARGET_TYPE, TARGET_ID, CREATED_TIME),
    KEY IDX_SCHEDULER_OPERATION_OPERATOR (OPERATOR_ID, CREATED_TIME),
    KEY IDX_SCHEDULER_OPERATION_TIME (CREATED_TIME)
) COMMENT='调度人工操作审计表';

-- PEACH_SCHEDULER_STATE_LOG.sql
CREATE TABLE PEACH_SCHEDULER_STATE_LOG
(
    ID             BIGINT       NOT NULL AUTO_INCREMENT COMMENT '状态日志主键',
    AGGREGATE_TYPE VARCHAR(32)  NOT NULL COMMENT '聚合类型：JOB、EXECUTION',
    AGGREGATE_ID   VARCHAR(128) NOT NULL COMMENT '聚合标识',
    FROM_STATE     VARCHAR(32)  NULL COMMENT '迁移前状态',
    EVENT          VARCHAR(32)  NOT NULL COMMENT '状态事件',
    TO_STATE       VARCHAR(32)  NOT NULL COMMENT '迁移后状态',
    OPERATOR_ID    VARCHAR(64)  NULL COMMENT '操作人 ID',
    REMARK         VARCHAR(512) NULL COMMENT '备注',
    CREATED_TIME   DATETIME(3)  NOT NULL COMMENT '创建时间',
    PRIMARY KEY (ID),
    KEY IDX_SCHEDULER_STATE_LOG_AGGREGATE (AGGREGATE_TYPE, AGGREGATE_ID, CREATED_TIME),
    KEY IDX_SCHEDULER_STATE_LOG_TIME (CREATED_TIME)
) COMMENT='调度状态迁移审计表';

-- PEACH_SITE_MESSAGE.sql
CREATE TABLE PEACH_SITE_MESSAGE
(
    ID                  VARCHAR(64)  NOT NULL COMMENT '消息ID',
    MESSAGE_CODE        VARCHAR(64)  NOT NULL COMMENT '消息编码',
    RECEIVER_ID         VARCHAR(64)  NOT NULL COMMENT '接收用户ID',
    TITLE_MESSAGE_KEY   VARCHAR(128) NULL COMMENT '标题消息Key',
    CONTENT_MESSAGE_KEY VARCHAR(128) NULL COMMENT '内容消息Key',
    MESSAGE_TYPE        VARCHAR(32)  NULL COMMENT '消息类型',
    SOURCE_TYPE         VARCHAR(32)  NULL COMMENT '来源类型',
    SOURCE_CODE         VARCHAR(64)  NULL COMMENT '来源编码',
    READ_FLAG           INT          NULL COMMENT '是否已读',
    SEND_STATUS         VARCHAR(32)  NULL COMMENT '发送状态',
    TENANT_ID           VARCHAR(32)  NOT NULL COMMENT '租户ID',
    ORG_ID              VARCHAR(32)  NOT NULL COMMENT '机构ID',
    CREATED_TIME        VARCHAR(20)  NULL COMMENT '创建时间',
    CREATOR_ID          VARCHAR(32)  NULL COMMENT '创建人ID',
    MODIFY_TIME         VARCHAR(20)  NULL COMMENT '修改时间',
    MODIFIER_ID         VARCHAR(32)  NULL COMMENT '修改人ID',
    PRIMARY KEY (ID),
    UNIQUE KEY UK_SITE_MESSAGE_CONTEXT_RECEIVER (TENANT_ID, ORG_ID, MESSAGE_CODE, RECEIVER_ID),
    INDEX IDX_SITE_MESSAGE_CONTEXT_RECEIVER (TENANT_ID, ORG_ID, RECEIVER_ID, READ_FLAG)
) COMMENT='站内消息表';

-- PEACH_STORAGE_INSTANCE.sql
CREATE TABLE PEACH_STORAGE_INSTANCE
(
    INSTANCE_ID          VARCHAR(64)  NOT NULL COMMENT '存储实例ID',
    INSTANCE_NAME        VARCHAR(128) NOT NULL COMMENT '存储实例名称',
    STORE_TYPE           VARCHAR(32)  NOT NULL COMMENT '存储类型',
    ENDPOINT             VARCHAR(512) DEFAULT NULL COMMENT '访问节点地址',
    REGION               VARCHAR(64)  DEFAULT NULL COMMENT '区域',
    BUCKET_NAME          VARCHAR(128) DEFAULT NULL COMMENT '存储桶名称',
    PREFIX               VARCHAR(512) DEFAULT NULL COMMENT '逻辑路径前缀',
    ACCESS_KEY           VARCHAR(256) DEFAULT NULL COMMENT '访问密钥',
    SECRET_KEY           VARCHAR(512) DEFAULT NULL COMMENT '加密后的私密密钥',
    ROOT_PATH            VARCHAR(512) DEFAULT NULL COMMENT '本地存储或NAS存储根路径',
    DOMAIN               VARCHAR(512) DEFAULT NULL COMMENT '公共访问域名',
    PATH_STYLE_ACCESS    TINYINT(1)   NOT NULL DEFAULT 0 COMMENT '是否启用Path Style访问，0否1是',
    PUBLIC_READ          TINYINT(1)   NOT NULL DEFAULT 0 COMMENT '是否允许公共读取，0否1是',
    EXTRA_JSON           JSON         DEFAULT NULL COMMENT '服务商扩展配置JSON',
    ENABLED              TINYINT(1)   NOT NULL DEFAULT 1 COMMENT '是否启用，0禁用1启用',
    BUILT_IN             TINYINT(1)   NOT NULL DEFAULT 0 COMMENT '是否内置，0否1是',
    TENANT_ID            VARCHAR(32)  NOT NULL COMMENT '租户ID',
    ORG_ID               VARCHAR(32)  NOT NULL COMMENT '机构ID',
    REMARK               VARCHAR(512) DEFAULT NULL COMMENT '备注',
    CREATED_TIME         VARCHAR(20)  DEFAULT NULL COMMENT '创建时间',
    CREATOR_ID           VARCHAR(32)  DEFAULT NULL COMMENT '创建人ID',
    MODIFY_TIME          VARCHAR(20)  DEFAULT NULL COMMENT '修改时间',
    MODIFIER_ID          VARCHAR(32)  DEFAULT NULL COMMENT '修改人ID',
    PRIMARY KEY (INSTANCE_ID),
    UNIQUE KEY UK_STORAGE_INSTANCE_CONTEXT_NAME (TENANT_ID, ORG_ID, INSTANCE_NAME),
    KEY IDX_STORAGE_INSTANCE_CONTEXT_TYPE (TENANT_ID, ORG_ID, STORE_TYPE),
    KEY IDX_STORAGE_INSTANCE_CONTEXT_ENABLE (TENANT_ID, ORG_ID, ENABLED),
    KEY IDX_STORAGE_INSTANCE_CONTEXT_TYPE_ENABLE (TENANT_ID, ORG_ID, STORE_TYPE, ENABLED)
) COMMENT='云存储实例定义表';

-- PEACH_TENANT.sql
CREATE TABLE PEACH_TENANT
(
    TENANT_ID    VARCHAR(32)  NOT NULL COMMENT '租户ID',
    TENANT_CODE  VARCHAR(64)  NOT NULL COMMENT '租户编码',
    TENANT_NAME  VARCHAR(128) NOT NULL COMMENT '租户名称',
    STATUS       VARCHAR(16)  DEFAULT 'ENABLE' COMMENT '状态',
    SORT_NUM     INT          DEFAULT 0 COMMENT '排序',
    IS_DELETE    INT          DEFAULT 0 COMMENT '逻辑删除',
    CREATED_TIME VARCHAR(20)  NULL COMMENT '创建时间',
    CREATOR_ID   VARCHAR(32)  NULL COMMENT '创建人ID',
    MODIFY_TIME  VARCHAR(20)  NULL COMMENT '修改时间',
    MODIFIER_ID  VARCHAR(32)  NULL COMMENT '修改人ID',
    PRIMARY KEY (TENANT_ID),
    UNIQUE KEY UK_TENANT_CODE (TENANT_CODE)
) COMMENT='租户表';

-- PEACH_USER.sql
CREATE TABLE PEACH_USER
(
    USER_ID            VARCHAR(32) NOT NULL COMMENT '用户ID',
    USER_CODE          VARCHAR(32) NULL COMMENT '用户账号',
    PASSWORD           VARCHAR(32) NULL COMMENT '用户密码',
    USER_NAME          VARCHAR(50) NULL COMMENT '用户名称',
    IDENTITY_CODE      VARCHAR(30) NULL COMMENT '用户身份证号',
    INVLIDATE          VARCHAR(20) NULL COMMENT '密码失效日期',
    AUTH_MODE          VARCHAR(20) NULL COMMENT '认证方式',
    STATUS             VARCHAR(20) NULL COMMENT '状态',
    UNLOCK_TIME        VARCHAR(20) NULL COMMENT '解锁时间',
    MENU_STYLE         VARCHAR(20) NULL COMMENT '菜单风格',
    MENU_ROLE          VARCHAR(128) NULL COMMENT '菜单角色',
    LASTEST_LOGIN      VARCHAR(20) NULL COMMENT '最近登录时间',
    ERROR_COUNT        VARCHAR(20) NULL COMMENT '密码错误次数',
    START_DATE         VARCHAR(20) NULL COMMENT '有效期开始',
    END_DATE           VARCHAR(20) NULL COMMENT '有效期结束',
    MOBILE_PHONE       VARCHAR(11) NULL COMMENT '手机号',
    EMAIL              VARCHAR(32) NULL COMMENT '邮箱',
    TENANT_ID  VARCHAR(32) NULL COMMENT '租户ID',
    DEFAULT_ORG_ID     VARCHAR(32) NULL COMMENT '默认机构ID',
    CREATED_TIME       VARCHAR(20) NULL COMMENT '创建时间',
    CREATOR_ID         VARCHAR(32) NULL COMMENT '创建人ID',
    MODIFY_TIME        VARCHAR(20) NULL COMMENT '修改时间',
    MODIFIER_ID        VARCHAR(32) NULL COMMENT '修改人ID',
    IS_DELETE          TINYINT(1) DEFAULT 0 COMMENT '是否删除',
    IS_MODIFY          TINYINT(1) DEFAULT 0 COMMENT '密码是否修改',
    PASSWD_MODIFY_TIME VARCHAR(20) NULL COMMENT '密码修改时间',
    PRIMARY KEY (USER_ID),
    UNIQUE KEY UK_USER_CODE (USER_CODE)
) COMMENT='用户信息表';

-- PEACH_USER_AVATAR_HISTORY.sql
CREATE TABLE PEACH_USER_AVATAR_HISTORY
(
    AVATAR_HISTORY_ID VARCHAR(32) NOT NULL COMMENT '头像历史ID',
    USER_ID           VARCHAR(32) NOT NULL COMMENT '用户ID',
    FILE_ID           VARCHAR(32) NOT NULL COMMENT '文件服务业务文件ID',
    SORT_NO           INT         NOT NULL COMMENT '排序号，1为最近使用',
    IS_CURRENT        TINYINT(1)  DEFAULT 0 COMMENT '是否当前头像',
    IS_DELETE         TINYINT(1)  DEFAULT 0 COMMENT '逻辑删除',
    CREATED_TIME      VARCHAR(20) NULL COMMENT '创建时间',
    CREATOR_ID        VARCHAR(32) NULL COMMENT '创建人ID',
    MODIFY_TIME       VARCHAR(20) NULL COMMENT '修改时间',
    MODIFIER_ID       VARCHAR(32) NULL COMMENT '修改人ID',
    PRIMARY KEY (AVATAR_HISTORY_ID),
    UNIQUE KEY UK_USER_AVATAR_FILE (USER_ID, FILE_ID),
    INDEX IDX_USER_AVATAR_ORDER (USER_ID, IS_DELETE, SORT_NO),
    INDEX IDX_USER_AVATAR_CURRENT (USER_ID, IS_CURRENT, IS_DELETE)
) COMMENT='用户头像历史表';

-- PEACH_USER_ORG.sql
CREATE TABLE PEACH_USER_ORG
(
    ID           VARCHAR(32) NOT NULL COMMENT '主键ID',
    USER_ID      VARCHAR(32) NOT NULL COMMENT '用户ID',
    TENANT_ID    VARCHAR(32) NOT NULL COMMENT '租户ID',
    ORG_ID       VARCHAR(32) NOT NULL COMMENT '机构ID',
    IS_DEFAULT   TINYINT(1) DEFAULT 0 COMMENT '是否默认机构',
    STATUS       VARCHAR(20) NULL COMMENT '状态',
    CREATED_TIME VARCHAR(20) NULL COMMENT '创建时间',
    CREATOR_ID   VARCHAR(32) NULL COMMENT '创建人ID',
    MODIFY_TIME  VARCHAR(20) NULL COMMENT '修改时间',
    MODIFIER_ID  VARCHAR(32) NULL COMMENT '修改人ID',
    IS_DELETE    TINYINT(1) DEFAULT 0 COMMENT '是否删除',
    PRIMARY KEY (ID),
    UNIQUE KEY UK_USER_ORG (TENANT_ID, USER_ID, ORG_ID),
    INDEX IDX_USER_ORG_USER (TENANT_ID, USER_ID),
    INDEX IDX_USER_ORG_ORG (TENANT_ID, ORG_ID)
) COMMENT='用户机构关系表';

-- PEACH_VALUE_SET.sql
CREATE TABLE PEACH_VALUE_SET
(
    ID            VARCHAR(64)  NOT NULL COMMENT '主键ID',
    VALUE_SET_CODE VARCHAR(64) NOT NULL COMMENT '值集编码',
    VALUE_SET_NAME VARCHAR(128) NULL COMMENT '值集名称',
    MODULE_CODE   VARCHAR(64)  NULL COMMENT '模块编码',
    SOURCE_TYPE   VARCHAR(32)  NULL COMMENT '来源类型',
    DESCRIPTION   VARCHAR(500) NULL COMMENT '描述',
    STATUS        INT          NULL COMMENT '状态',
    TENANT_ID     VARCHAR(32)  NOT NULL COMMENT '租户ID',
    ORG_ID        VARCHAR(32)  NOT NULL COMMENT '机构ID',
    CREATED_TIME  VARCHAR(20)  NULL COMMENT '创建时间',
    CREATOR_ID    VARCHAR(32)  NULL COMMENT '创建人ID',
    MODIFY_TIME   VARCHAR(20)  NULL COMMENT '修改时间',
    MODIFIER_ID   VARCHAR(32)  NULL COMMENT '修改人ID',
    PRIMARY KEY (ID),
    UNIQUE KEY UK_VALUE_SET_CONTEXT_CODE (TENANT_ID, ORG_ID, VALUE_SET_CODE),
    INDEX IDX_VALUE_SET_CONTEXT (TENANT_ID, ORG_ID)
) COMMENT='值集配置表';

-- PEACH_VALUE_SET_ITEM.sql
CREATE TABLE PEACH_VALUE_SET_ITEM
(
    ID            VARCHAR(64)  NOT NULL COMMENT '主键ID',
    VALUE_SET_CODE VARCHAR(64) NOT NULL COMMENT '值集编码',
    ITEM_CODE     VARCHAR(64)  NOT NULL COMMENT '项编码',
    ITEM_VALUE    VARCHAR(255) NULL COMMENT '项值',
    MESSAGE_KEY   VARCHAR(128) NULL COMMENT '国际化Key',
    SOURCE_TYPE   VARCHAR(32)  NULL COMMENT '来源类型',
    SORT_ORDER    INT          NULL COMMENT '排序号',
    STATUS        INT          NULL COMMENT '状态',
    VISIBLE_FLAG  INT          NULL COMMENT '是否可见',
    EXTRA_JSON    TEXT         NULL COMMENT '扩展JSON',
    TENANT_ID     VARCHAR(32)  NOT NULL COMMENT '租户ID',
    ORG_ID        VARCHAR(32)  NOT NULL COMMENT '机构ID',
    CREATED_TIME  VARCHAR(20)  NULL COMMENT '创建时间',
    CREATOR_ID    VARCHAR(32)  NULL COMMENT '创建人ID',
    MODIFY_TIME   VARCHAR(20)  NULL COMMENT '修改时间',
    MODIFIER_ID   VARCHAR(32)  NULL COMMENT '修改人ID',
    PRIMARY KEY (ID),
    UNIQUE KEY UK_VALUE_SET_ITEM_CONTEXT_CODE (TENANT_ID, ORG_ID, VALUE_SET_CODE, ITEM_CODE),
    INDEX IDX_VALUE_SET_ITEM_CONTEXT_SET (TENANT_ID, ORG_ID, VALUE_SET_CODE)
) COMMENT='值集项表';

-- MQ_CONSUME_RECORD.sql
-- RocketMQ JDBC 消费幂等记录表（peach-scheduler-transport-rocket）

CREATE TABLE MQ_CONSUME_RECORD
(
    ID              BIGINT       NOT NULL AUTO_INCREMENT COMMENT '主键 ID',
    IDEMPOTENT_KEY  VARCHAR(256) NOT NULL COMMENT '幂等键',
    CONSUMER_GROUP  VARCHAR(128) NOT NULL COMMENT '消费者组',
    TOPIC           VARCHAR(128) NULL COMMENT 'RocketMQ Topic',
    TAG             VARCHAR(128) NULL COMMENT 'RocketMQ Tag',
    BUSINESS_KEY    VARCHAR(128) NULL COMMENT '业务 Key',
    MESSAGE_ID      VARCHAR(128) NULL COMMENT '消息 ID',
    STATUS          VARCHAR(32)  NOT NULL COMMENT '状态：PROCESSING、SUCCESS、FAILED',
    CONSUME_COUNT   INT          NOT NULL DEFAULT 0 COMMENT '消费次数',
    LAST_ERROR      VARCHAR(1000) NULL COMMENT '脱敏后的最近错误',
    CREATED_AT      DATETIME(3)  NOT NULL COMMENT '创建时间',
    UPDATED_AT      DATETIME(3)  NOT NULL COMMENT '更新时间',
    PRIMARY KEY (ID),
    UNIQUE KEY UK_MQ_CONSUME_IDEMPOTENT (IDEMPOTENT_KEY, CONSUMER_GROUP),
    KEY IDX_MQ_CONSUME_MESSAGE (MESSAGE_ID),
    KEY IDX_MQ_CONSUME_STATUS_UPDATE (STATUS, UPDATED_AT)
) COMMENT='RocketMQ JDBC 消费幂等记录表';

-- MQ_OUTBOX_EVENT.sql
-- RocketMQ JDBC Outbox 可靠消息表（peach-scheduled / peach-scheduler-transport-rocket）

CREATE TABLE MQ_OUTBOX_EVENT
(
    ID                 BIGINT       NOT NULL AUTO_INCREMENT COMMENT '主键 ID',
    MESSAGE_ID         VARCHAR(64)  NOT NULL COMMENT '消息唯一 ID',
    TOPIC              VARCHAR(128) NOT NULL COMMENT 'RocketMQ Topic',
    TAG                VARCHAR(128) NULL COMMENT 'RocketMQ Tag',
    BUSINESS_KEY       VARCHAR(128) NULL COMMENT '业务 Key，通常为 executionId',
    PAYLOAD            LONGTEXT     NOT NULL COMMENT 'Base64 编码后的标准消息 Envelope',
    SEND_MODE          VARCHAR(32)  NOT NULL DEFAULT 'NORMAL' COMMENT '发送模式：NORMAL、ORDERLY、DELAY',
    SHARDING_KEY       VARCHAR(128) NULL COMMENT '顺序消息分片键',
    DELAY_LEVEL        INT          NULL COMMENT 'RocketMQ 延迟级别',
    PAYLOAD_TYPE       VARCHAR(256) NULL COMMENT 'Payload 类型名称',
    HEADERS            TEXT         NULL COMMENT '消息 Headers 快照，禁止写入敏感字段',
    STATUS             VARCHAR(32)  NOT NULL COMMENT '状态：INIT、SENDING、SENT、RETRY、FAILED',
    RETRY_COUNT        INT          NOT NULL DEFAULT 0 COMMENT '重试次数',
    NEXT_RETRY_TIME    DATETIME(3)  NOT NULL COMMENT '下次可重试时间',
    LAST_ERROR         VARCHAR(1000) NULL COMMENT '脱敏后的最近错误',
    BROKER_MESSAGE_ID  VARCHAR(128) NULL COMMENT 'Broker 返回的消息 ID',
    CLAIMED_BY         VARCHAR(128) NULL COMMENT 'Outbox 抢占实例标识',
    CLAIMED_AT         DATETIME(3)  NULL COMMENT 'Outbox 抢占时间',
    SENT_AT            DATETIME(3)  NULL COMMENT '投递成功时间',
    CREATED_AT         DATETIME(3)  NOT NULL COMMENT '创建时间',
    UPDATED_AT         DATETIME(3)  NOT NULL COMMENT '更新时间',
    PRIMARY KEY (ID),
    UNIQUE KEY UK_MQ_OUTBOX_MESSAGE (MESSAGE_ID),
    KEY IDX_MQ_OUTBOX_STATUS_RETRY (STATUS, NEXT_RETRY_TIME),
    KEY IDX_MQ_OUTBOX_STATUS_CLAIMED (STATUS, CLAIMED_AT),
    KEY IDX_MQ_OUTBOX_TOPIC_KEY (TOPIC, BUSINESS_KEY)
) COMMENT='RocketMQ JDBC Outbox 可靠消息表';

-- QRTZ_MYSQL.sql
-- Quartz JDBC JobStore 集群表（peach-scheduled Quartz Provider 运行时投影，非任务事实源）
-- 事实源见 PEACH_SCHEDULER_* 单表脚本；Scheduler 名称默认为 peachScheduler

CREATE TABLE QRTZ_JOB_DETAILS
(
    SCHED_NAME        VARCHAR(120) NOT NULL COMMENT 'Scheduler 名称',
    JOB_NAME          VARCHAR(200) NOT NULL COMMENT 'Job 名称',
    JOB_GROUP         VARCHAR(200) NOT NULL COMMENT 'Job 分组',
    DESCRIPTION       VARCHAR(250) NULL COMMENT 'Job 描述',
    JOB_CLASS_NAME    VARCHAR(250) NOT NULL COMMENT 'Job 实现类全名',
    IS_DURABLE        VARCHAR(1)   NOT NULL COMMENT '是否持久化',
    IS_NONCONCURRENT  VARCHAR(1)   NOT NULL COMMENT '是否禁止并发',
    IS_UPDATE_DATA    VARCHAR(1)   NOT NULL COMMENT '是否更新 JobData',
    REQUESTS_RECOVERY VARCHAR(1)   NOT NULL COMMENT '是否请求恢复',
    JOB_DATA          BLOB         NULL COMMENT 'Job 附加数据',
    PRIMARY KEY (SCHED_NAME, JOB_NAME, JOB_GROUP)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COMMENT='Quartz Job 详情表';

CREATE TABLE QRTZ_TRIGGERS
(
    SCHED_NAME     VARCHAR(120) NOT NULL COMMENT 'Scheduler 名称',
    TRIGGER_NAME   VARCHAR(200) NOT NULL COMMENT 'Trigger 名称',
    TRIGGER_GROUP  VARCHAR(200) NOT NULL COMMENT 'Trigger 分组',
    JOB_NAME       VARCHAR(200) NOT NULL COMMENT '关联 Job 名称',
    JOB_GROUP      VARCHAR(200) NOT NULL COMMENT '关联 Job 分组',
    DESCRIPTION    VARCHAR(250) NULL COMMENT 'Trigger 描述',
    NEXT_FIRE_TIME BIGINT(13)   NULL COMMENT '下次触发时间戳',
    PREV_FIRE_TIME BIGINT(13)   NULL COMMENT '上次触发时间戳',
    PRIORITY       INTEGER      NULL COMMENT '优先级',
    TRIGGER_STATE  VARCHAR(16)  NOT NULL COMMENT 'Trigger 状态',
    TRIGGER_TYPE   VARCHAR(8)   NOT NULL COMMENT 'Trigger 类型',
    START_TIME     BIGINT(13)   NOT NULL COMMENT '开始时间戳',
    END_TIME       BIGINT(13)   NULL COMMENT '结束时间戳',
    CALENDAR_NAME  VARCHAR(200) NULL COMMENT '日历名称',
    MISFIRE_INSTR  SMALLINT(2)  NULL COMMENT 'Misfire 指令',
    JOB_DATA       BLOB         NULL COMMENT 'Trigger 附加数据',
    PRIMARY KEY (SCHED_NAME, TRIGGER_NAME, TRIGGER_GROUP),
    KEY IDX_QRTZ_T_J (SCHED_NAME, JOB_NAME, JOB_GROUP),
    KEY IDX_QRTZ_T_JG (SCHED_NAME, JOB_GROUP),
    KEY IDX_QRTZ_T_C (SCHED_NAME, CALENDAR_NAME),
    KEY IDX_QRTZ_T_G (SCHED_NAME, TRIGGER_GROUP),
    KEY IDX_QRTZ_T_STATE (SCHED_NAME, TRIGGER_STATE),
    KEY IDX_QRTZ_T_N_STATE (SCHED_NAME, TRIGGER_NAME, TRIGGER_GROUP, TRIGGER_STATE),
    KEY IDX_QRTZ_T_N_G_STATE (SCHED_NAME, TRIGGER_GROUP, TRIGGER_STATE),
    KEY IDX_QRTZ_T_NEXT_FIRE_TIME (SCHED_NAME, NEXT_FIRE_TIME),
    KEY IDX_QRTZ_T_NFT_ST (SCHED_NAME, TRIGGER_STATE, NEXT_FIRE_TIME),
    KEY IDX_QRTZ_T_NFT_MISFIRE (SCHED_NAME, MISFIRE_INSTR, NEXT_FIRE_TIME),
    KEY IDX_QRTZ_T_NFT_ST_MISFIRE (SCHED_NAME, MISFIRE_INSTR, NEXT_FIRE_TIME, TRIGGER_STATE),
    KEY IDX_QRTZ_T_NFT_ST_MISFIRE_GRP (SCHED_NAME, MISFIRE_INSTR, NEXT_FIRE_TIME, TRIGGER_GROUP, TRIGGER_STATE)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COMMENT='Quartz Trigger 表';

CREATE TABLE QRTZ_SIMPLE_TRIGGERS
(
    SCHED_NAME      VARCHAR(120) NOT NULL COMMENT 'Scheduler 名称',
    TRIGGER_NAME    VARCHAR(200) NOT NULL COMMENT 'Trigger 名称',
    TRIGGER_GROUP   VARCHAR(200) NOT NULL COMMENT 'Trigger 分组',
    REPEAT_COUNT    BIGINT(7)    NOT NULL COMMENT '重复次数',
    REPEAT_INTERVAL BIGINT(12)   NOT NULL COMMENT '重复间隔毫秒数',
    TIMES_TRIGGERED BIGINT(10)   NOT NULL COMMENT '已触发次数',
    PRIMARY KEY (SCHED_NAME, TRIGGER_NAME, TRIGGER_GROUP)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COMMENT='Quartz Simple Trigger 表';

CREATE TABLE QRTZ_CRON_TRIGGERS
(
    SCHED_NAME      VARCHAR(120) NOT NULL COMMENT 'Scheduler 名称',
    TRIGGER_NAME    VARCHAR(200) NOT NULL COMMENT 'Trigger 名称',
    TRIGGER_GROUP   VARCHAR(200) NOT NULL COMMENT 'Trigger 分组',
    CRON_EXPRESSION VARCHAR(120) NOT NULL COMMENT 'Cron 表达式',
    TIME_ZONE_ID    VARCHAR(80)  NULL COMMENT '时区 ID',
    PRIMARY KEY (SCHED_NAME, TRIGGER_NAME, TRIGGER_GROUP)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COMMENT='Quartz Cron Trigger 表';

CREATE TABLE QRTZ_SIMPROP_TRIGGERS
(
    SCHED_NAME    VARCHAR(120)   NOT NULL COMMENT 'Scheduler 名称',
    TRIGGER_NAME  VARCHAR(200)   NOT NULL COMMENT 'Trigger 名称',
    TRIGGER_GROUP VARCHAR(200)   NOT NULL COMMENT 'Trigger 分组',
    STR_PROP_1    VARCHAR(512)   NULL COMMENT '字符串属性 1',
    STR_PROP_2    VARCHAR(512)   NULL COMMENT '字符串属性 2',
    STR_PROP_3    VARCHAR(512)   NULL COMMENT '字符串属性 3',
    INT_PROP_1    INT            NULL COMMENT '整型属性 1',
    INT_PROP_2    INT            NULL COMMENT '整型属性 2',
    LONG_PROP_1   BIGINT         NULL COMMENT '长整型属性 1',
    LONG_PROP_2   BIGINT         NULL COMMENT '长整型属性 2',
    DEC_PROP_1    NUMERIC(13, 4) NULL COMMENT '小数属性 1',
    DEC_PROP_2    NUMERIC(13, 4) NULL COMMENT '小数属性 2',
    BOOL_PROP_1   VARCHAR(1)     NULL COMMENT '布尔属性 1',
    BOOL_PROP_2   VARCHAR(1)     NULL COMMENT '布尔属性 2',
    PRIMARY KEY (SCHED_NAME, TRIGGER_NAME, TRIGGER_GROUP)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COMMENT='Quartz 属性 Trigger 表';

CREATE TABLE QRTZ_BLOB_TRIGGERS
(
    SCHED_NAME    VARCHAR(120) NOT NULL COMMENT 'Scheduler 名称',
    TRIGGER_NAME  VARCHAR(200) NOT NULL COMMENT 'Trigger 名称',
    TRIGGER_GROUP VARCHAR(200) NOT NULL COMMENT 'Trigger 分组',
    BLOB_DATA     BLOB         NULL COMMENT '二进制 Trigger 数据',
    PRIMARY KEY (SCHED_NAME, TRIGGER_NAME, TRIGGER_GROUP)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COMMENT='Quartz Blob Trigger 表';

CREATE TABLE QRTZ_CALENDARS
(
    SCHED_NAME    VARCHAR(120) NOT NULL COMMENT 'Scheduler 名称',
    CALENDAR_NAME VARCHAR(200) NOT NULL COMMENT '日历名称',
    CALENDAR      BLOB         NOT NULL COMMENT '日历二进制数据',
    PRIMARY KEY (SCHED_NAME, CALENDAR_NAME)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COMMENT='Quartz 日历表';

CREATE TABLE QRTZ_PAUSED_TRIGGER_GRPS
(
    SCHED_NAME    VARCHAR(120) NOT NULL COMMENT 'Scheduler 名称',
    TRIGGER_GROUP VARCHAR(200) NOT NULL COMMENT '已暂停 Trigger 分组',
    PRIMARY KEY (SCHED_NAME, TRIGGER_GROUP)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COMMENT='Quartz 暂停 Trigger 分组表';

CREATE TABLE QRTZ_FIRED_TRIGGERS
(
    SCHED_NAME        VARCHAR(120) NOT NULL COMMENT 'Scheduler 名称',
    ENTRY_ID          VARCHAR(95)  NOT NULL COMMENT '触发记录 ID',
    TRIGGER_NAME      VARCHAR(200) NOT NULL COMMENT 'Trigger 名称',
    TRIGGER_GROUP     VARCHAR(200) NOT NULL COMMENT 'Trigger 分组',
    INSTANCE_NAME     VARCHAR(200) NOT NULL COMMENT 'Scheduler 实例名称',
    FIRED_TIME        BIGINT(13)   NOT NULL COMMENT '实际触发时间戳',
    SCHED_TIME        BIGINT(13)   NOT NULL COMMENT '计划触发时间戳',
    PRIORITY          INTEGER      NOT NULL COMMENT '优先级',
    STATE             VARCHAR(16)  NOT NULL COMMENT '触发状态',
    JOB_NAME          VARCHAR(200) NULL COMMENT 'Job 名称',
    JOB_GROUP         VARCHAR(200) NULL COMMENT 'Job 分组',
    IS_NONCONCURRENT  VARCHAR(1)   NULL COMMENT '是否禁止并发',
    REQUESTS_RECOVERY VARCHAR(1)   NULL COMMENT '是否请求恢复',
    PRIMARY KEY (SCHED_NAME, ENTRY_ID),
    KEY IDX_QRTZ_FT_TRIG_INST_NAME (SCHED_NAME, INSTANCE_NAME),
    KEY IDX_QRTZ_FT_INST_JOB_REQ_RCVRY (SCHED_NAME, INSTANCE_NAME, REQUESTS_RECOVERY),
    KEY IDX_QRTZ_FT_J_G (SCHED_NAME, JOB_NAME, JOB_GROUP),
    KEY IDX_QRTZ_FT_JG (SCHED_NAME, JOB_GROUP),
    KEY IDX_QRTZ_FT_T_G (SCHED_NAME, TRIGGER_NAME, TRIGGER_GROUP),
    KEY IDX_QRTZ_FT_TG (SCHED_NAME, TRIGGER_GROUP)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COMMENT='Quartz 已触发 Trigger 表';

CREATE TABLE QRTZ_SCHEDULER_STATE
(
    SCHED_NAME        VARCHAR(120) NOT NULL COMMENT 'Scheduler 名称',
    INSTANCE_NAME     VARCHAR(200) NOT NULL COMMENT 'Scheduler 实例名称',
    LAST_CHECKIN_TIME BIGINT(13)   NOT NULL COMMENT '最近检入时间戳',
    CHECKIN_INTERVAL  BIGINT(13)   NOT NULL COMMENT '检入间隔毫秒数',
    PRIMARY KEY (SCHED_NAME, INSTANCE_NAME)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COMMENT='Quartz 集群实例状态表';

CREATE TABLE QRTZ_LOCKS
(
    SCHED_NAME VARCHAR(120) NOT NULL COMMENT 'Scheduler 名称',
    LOCK_NAME  VARCHAR(40)  NOT NULL COMMENT '锁名称',
    PRIMARY KEY (SCHED_NAME, LOCK_NAME)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COMMENT='Quartz 集群锁表';

ALTER TABLE QRTZ_TRIGGERS
    ADD CONSTRAINT QRTZ_TRIGGERS_JOB_DETAILS_FK
        FOREIGN KEY (SCHED_NAME, JOB_NAME, JOB_GROUP)
            REFERENCES QRTZ_JOB_DETAILS (SCHED_NAME, JOB_NAME, JOB_GROUP);

ALTER TABLE QRTZ_SIMPLE_TRIGGERS
    ADD CONSTRAINT QRTZ_SIMPLE_TRIGGERS_TRIGGERS_FK
        FOREIGN KEY (SCHED_NAME, TRIGGER_NAME, TRIGGER_GROUP)
            REFERENCES QRTZ_TRIGGERS (SCHED_NAME, TRIGGER_NAME, TRIGGER_GROUP)
            ON DELETE CASCADE;

ALTER TABLE QRTZ_CRON_TRIGGERS
    ADD CONSTRAINT QRTZ_CRON_TRIGGERS_TRIGGERS_FK
        FOREIGN KEY (SCHED_NAME, TRIGGER_NAME, TRIGGER_GROUP)
            REFERENCES QRTZ_TRIGGERS (SCHED_NAME, TRIGGER_NAME, TRIGGER_GROUP)
            ON DELETE CASCADE;

ALTER TABLE QRTZ_SIMPROP_TRIGGERS
    ADD CONSTRAINT QRTZ_SIMPROP_TRIGGERS_TRIGGERS_FK
        FOREIGN KEY (SCHED_NAME, TRIGGER_NAME, TRIGGER_GROUP)
            REFERENCES QRTZ_TRIGGERS (SCHED_NAME, TRIGGER_NAME, TRIGGER_GROUP)
            ON DELETE CASCADE;

ALTER TABLE QRTZ_BLOB_TRIGGERS
    ADD CONSTRAINT QRTZ_BLOB_TRIGGERS_TRIGGERS_FK
        FOREIGN KEY (SCHED_NAME, TRIGGER_NAME, TRIGGER_GROUP)
            REFERENCES QRTZ_TRIGGERS (SCHED_NAME, TRIGGER_NAME, TRIGGER_GROUP)
            ON DELETE CASCADE;

